 "ruled_out": [
  {
   "statement": "A latency or timeout cascade is unlikely. No service has a p95 latency onset, and inventory p95 peaks at 47ms, orders at 99ms and gateway at 140ms.",
   "evidence_ids": [
    "ev-4081415f77fb",
    "ev-e960c3ed491b",
    "ev-03f01a29eb0b"
   ]
  },
  {
   "statement": "A traffic surge is not evident. Gateway request rate stays around 2 req/s (avg 2.07, max 2.42) and is lower at the end (1.78).",
   "evidence_ids": [
    "ev-03f01a29eb0b"
   ]
  },
  {
   "statement": "Gateway and orders are unlikely to be the origin. Their errors explicitly cite failures from the downstream service (orders 502 and inventory 500, respectively).",
   "evidence_ids": [
    "ev-bf38338a2a0a",
    "ev-668d724aaa57"
   ]
  }
 ],
 "unknowns": [
  "Which peer resets inventory's connections (database, cache, or another service) is not identified. No metrics or logs exist for inventory's dependencies.",
  "Trace data is missing because the traces query timed out. Trace evidence could confirm the call path and where self time and errors originate.",
  "No deployment records are in the snapshot. It is unknown whether inventory 3.1.5 or any dependency changed shortly before 08:19:37Z.",
  "It is unknown whether the resets come from the peer side (e.g., restarts, connection limits, idle timeouts) or from inventory's client or connection pool configuration.",
  "Error ratios were still at their maximum at the end of the window, so the incident appears to be ongoing or worsening."
 ],
